-- Thông tin bổ sung cho bộ gốc (chạy "sửa từ thiếu info" một lần cho mọi user):
-- IPA Oxford US (CMU khi Oxford không có), URL mp3 Oxford US, hình Pexels cho từ
-- và cho từng câu ví dụ. Sinh bởi scripts/enrich-preset-decks.mjs +
-- scripts/gen-preset-decks-seed.mjs --enrich.
ALTER TABLE preset_deck_cards ADD COLUMN ipa TEXT;
ALTER TABLE preset_deck_cards ADD COLUMN audio_src TEXT;
ALTER TABLE preset_deck_cards ADD COLUMN image_url TEXT;
ALTER TABLE preset_deck_cards ADD COLUMN image_attribution TEXT;

-- ngsl-1-01
UPDATE preset_deck_cards SET ipa = '/seɪ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/say/say__/say__us_1.mp3', image_url = 'https://images.pexels.com/photos/6037811/pexels-photo-6037811.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Brett Jordan","author_url":"https://www.pexels.com/@brettjordan","source_url":"https://www.pexels.com/photo/wooden-scrabbles-pieces-on-white-table-6037811/"}', examples = '[{"en":"What did she say when you told her the news?","vi":"Cô ấy đã nói gì khi bạn báo tin cho cô ấy?","image_url":"https://images.pexels.com/photos/35467808/pexels-photo-35467808.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My doctor said I should drink more water.","vi":"Bác sĩ nói tôi nên uống nhiều nước hơn.","image_url":"https://images.pexels.com/photos/35232336/pexels-photo-35232336.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The sign says the museum is closed on Mondays.","vi":"Biển báo cho biết bảo tàng đóng cửa vào thứ Hai.","image_url":"https://images.pexels.com/photos/30253419/pexels-photo-30253419.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'say';
UPDATE preset_deck_cards SET ipa = '/ɡəʊ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/go_/go__u/go__us_1.mp3', image_url = 'https://images.pexels.com/photos/5640497/pexels-photo-5640497.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Tima Miroshnichenko","author_url":"https://www.pexels.com/@tima-miroshnichenko","source_url":"https://www.pexels.com/photo/man-in-white-helmet-riding-on-go-kart-5640497/"}', examples = '[{"en":"We usually go to the beach on weekends.","vi":"Chúng tôi thường đi biển vào cuối tuần.","image_url":"https://images.pexels.com/photos/10001094/pexels-photo-10001094.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She went home early because she felt tired.","vi":"Cô ấy về nhà sớm vì cảm thấy mệt.","image_url":"https://images.pexels.com/photos/17975075/pexels-photo-17975075.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"How did your job interview go yesterday?","vi":"Buổi phỏng vấn xin việc hôm qua của bạn diễn ra thế nào?","image_url":"https://images.pexels.com/photos/5922068/pexels-photo-5922068.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'go';
UPDATE preset_deck_cards SET ipa = '/nəʊ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/know_/know__us_1.mp3', image_url = 'https://images.pexels.com/photos/37549154/pexels-photo-37549154.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Giant Asparagus","author_url":"https://www.pexels.com/@giantasparagus","source_url":"https://www.pexels.com/photo/solar-powered-surveillance-camera-on-street-pole-37549154/"}', examples = '[{"en":"Do you know where the nearest bus stop is?","vi":"Bạn có biết trạm xe buýt gần nhất ở đâu không?","image_url":"https://images.pexels.com/photos/16252896/pexels-photo-16252896.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She didn''t know the answer, so she asked her teacher.","vi":"Cô ấy không biết câu trả lời nên đã hỏi giáo viên.","image_url":"https://images.pexels.com/photos/4936021/pexels-photo-4936021.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I have known my best friend since elementary school.","vi":"Tôi quen người bạn thân nhất của mình từ hồi tiểu học.","image_url":"https://images.pexels.com/photos/5896631/pexels-photo-5896631.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'know';
UPDATE preset_deck_cards SET ipa = '/mɔːr/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/more_/more__us_1.mp3', image_url = 'https://images.pexels.com/photos/15387083/pexels-photo-15387083.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Ann H","author_url":"https://www.pexels.com/@ann-h-45017","source_url":"https://www.pexels.com/photo/letters-on-dice-15387083/"}', examples = '[{"en":"We need more time to finish the project.","vi":"Chúng tôi cần thêm thời gian để hoàn thành dự án.","image_url":"https://images.pexels.com/photos/33266834/pexels-photo-33266834.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Could I have some more rice, please?","vi":"Cho tôi xin thêm một chút cơm được không?","image_url":"https://images.pexels.com/photos/13518953/pexels-photo-13518953.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"More people are working from home these days.","vi":"Dạo này có nhiều người làm việc tại nhà hơn.","image_url":"https://images.pexels.com/photos/11569938/pexels-photo-11569938.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'more';
UPDATE preset_deck_cards SET ipa = '/ɡet/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/get/get__/get__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I got a message from my sister this morning.","vi":"Sáng nay tôi nhận được tin nhắn từ chị gái.","image_url":"https://images.pexels.com/photos/6669776/pexels-photo-6669776.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Can you get me a glass of water?","vi":"Bạn lấy giúp tôi một cốc nước được không?","image_url":"https://images.pexels.com/photos/5336940/pexels-photo-5336940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It gets dark very early in the winter.","vi":"Vào mùa đông, trời tối rất sớm.","image_url":"https://images.pexels.com/photos/9807696/pexels-photo-9807696.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'get';
UPDATE preset_deck_cards SET ipa = '/laɪk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lik/like_/like__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I like reading books before I go to bed.","vi":"Tôi thích đọc sách trước khi đi ngủ.","image_url":"https://images.pexels.com/photos/29171842/pexels-photo-29171842.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My kids don''t like vegetables very much.","vi":"Bọn trẻ nhà tôi không thích ăn rau lắm.","image_url":"https://images.pexels.com/photos/4721131/pexels-photo-4721131.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She really likes her new apartment near the park.","vi":"Cô ấy rất thích căn hộ mới gần công viên.","image_url":"https://images.pexels.com/photos/7322273/pexels-photo-7322273.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'like';
UPDATE preset_deck_cards SET ipa = '/θɪŋk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/think/think__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I think it''s going to rain this afternoon.","vi":"Tôi nghĩ chiều nay trời sẽ mưa.","image_url":"https://images.pexels.com/photos/39275252/pexels-photo-39275252.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What do you think of the new teacher?","vi":"Bạn nghĩ gì về giáo viên mới?","image_url":"https://images.pexels.com/photos/39190904/pexels-photo-39190904.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"He is thinking about changing jobs next year.","vi":"Anh ấy đang nghĩ đến chuyện đổi việc vào năm sau.","image_url":"https://images.pexels.com/photos/5668885/pexels-photo-5668885.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'think';
UPDATE preset_deck_cards SET ipa = '/meɪk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mak/make_/make__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"My mom is making dinner in the kitchen.","vi":"Mẹ tôi đang làm bữa tối trong bếp.","image_url":"https://images.pexels.com/photos/5907924/pexels-photo-5907924.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This company makes furniture for schools and offices.","vi":"Công ty này sản xuất đồ nội thất cho trường học và văn phòng.","image_url":"https://images.pexels.com/photos/38816548/pexels-photo-38816548.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"That sad movie made everyone in the room cry.","vi":"Bộ phim buồn đó khiến mọi người trong phòng đều khóc.","image_url":"https://images.pexels.com/photos/9999344/pexels-photo-9999344.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'make';
UPDATE preset_deck_cards SET ipa = '/taɪm/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tim/time_/time__us_1.mp3', image_url = 'https://images.pexels.com/photos/8573370/pexels-photo-8573370.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Towfiqu barbhuiya","author_url":"https://www.pexels.com/@towfiqu-barbhuiya-3440682","source_url":"https://www.pexels.com/photo/hourglass-8573370/"}', examples = '[{"en":"I don''t have much free time during the week.","vi":"Trong tuần tôi không có nhiều thời gian rảnh.","image_url":"https://images.pexels.com/photos/1059381/pexels-photo-1059381.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I''ve called him three times, but he isn''t answering.","vi":"Tôi đã gọi cho anh ấy ba lần nhưng anh ấy không nghe máy.","image_url":"https://images.pexels.com/photos/8682791/pexels-photo-8682791.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What time does the next train leave?","vi":"Chuyến tàu tiếp theo khởi hành lúc mấy giờ?","image_url":"https://images.pexels.com/photos/5868296/pexels-photo-5868296.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'time';
UPDATE preset_deck_cards SET ipa = '/siː/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/see__/see__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Did you see the rainbow after the rain?","vi":"Bạn có thấy cầu vồng sau cơn mưa không?","image_url":"https://images.pexels.com/photos/36798456/pexels-photo-36798456.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I''m going to see my grandparents this weekend.","vi":"Cuối tuần này tôi sẽ đi thăm ông bà.","image_url":"https://images.pexels.com/photos/8307601/pexels-photo-8307601.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I see what you mean now, thank you.","vi":"Giờ thì tôi hiểu ý bạn rồi, cảm ơn nhé.","image_url":"https://images.pexels.com/photos/791024/pexels-photo-791024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'see';
UPDATE preset_deck_cards SET ipa = '/ɡʊd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/goo/good_/good__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Eating fruit every day is good for your health.","vi":"Ăn trái cây mỗi ngày tốt cho sức khỏe.","image_url":"https://images.pexels.com/photos/36600220/pexels-photo-36600220.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She is very good at math and science.","vi":"Cô ấy rất giỏi toán và khoa học.","image_url":"https://images.pexels.com/photos/6256109/pexels-photo-6256109.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You should watch that movie because it''s really good.","vi":"Bạn nên xem bộ phim đó vì nó rất hay.","image_url":"https://images.pexels.com/photos/7234319/pexels-photo-7234319.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'good';
UPDATE preset_deck_cards SET ipa = '/ˈpiːpl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/peo/peopl/people__us_4.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Many people take the bus to work in this city.","vi":"Ở thành phố này, nhiều người đi làm bằng xe buýt.","image_url":"https://images.pexels.com/photos/205353/pexels-photo-205353.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"How many people are coming to your party?","vi":"Có bao nhiêu người sẽ đến bữa tiệc của bạn?","image_url":"https://images.pexels.com/photos/36071198/pexels-photo-36071198.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"People are usually very friendly in small towns.","vi":"Ở các thị trấn nhỏ, mọi người thường rất thân thiện.","image_url":"https://images.pexels.com/photos/36722684/pexels-photo-36722684.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'people';
UPDATE preset_deck_cards SET ipa = '/jɪr/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yea/year_/year__us_1.mp3', image_url = 'https://images.pexels.com/photos/6354023/pexels-photo-6354023.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Lisa Fotios","author_url":"https://www.pexels.com/@fotios-photos","source_url":"https://www.pexels.com/photo/a-man-holding-a-paper-with-message-6354023/"}', examples = '[{"en":"We moved to this city three years ago.","vi":"Chúng tôi chuyển đến thành phố này ba năm trước.","image_url":"https://images.pexels.com/photos/7971291/pexels-photo-7971291.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She travels abroad at least once a year.","vi":"Cô ấy đi du lịch nước ngoài ít nhất mỗi năm một lần.","image_url":"https://images.pexels.com/photos/36485537/pexels-photo-36485537.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My son will be seven years old next month.","vi":"Tháng sau con trai tôi sẽ tròn bảy tuổi.","image_url":"https://images.pexels.com/photos/27175710/pexels-photo-27175710.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'year';
UPDATE preset_deck_cards SET ipa = '/teɪk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tak/take_/take__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"She took a book from the shelf and started reading.","vi":"Cô ấy lấy một cuốn sách trên kệ và bắt đầu đọc.","image_url":"https://images.pexels.com/photos/17975078/pexels-photo-17975078.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Don''t forget to take an umbrella with you.","vi":"Đừng quên mang theo ô nhé.","image_url":"https://images.pexels.com/photos/6874991/pexels-photo-6874991.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It takes about twenty minutes to walk to school.","vi":"Đi bộ đến trường mất khoảng hai mươi phút.","image_url":"https://images.pexels.com/photos/4881154/pexels-photo-4881154.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'take';
UPDATE preset_deck_cards SET ipa = '/wel/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/well_/well__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I didn''t sleep well last night because of the noise.","vi":"Đêm qua tôi ngủ không ngon vì tiếng ồn.","image_url":"https://images.pexels.com/photos/7556638/pexels-photo-7556638.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My brother can speak English and French very well.","vi":"Anh trai tôi nói tiếng Anh và tiếng Pháp rất giỏi.","image_url":"https://images.pexels.com/photos/39490137/pexels-photo-39490137.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Shake the bottle well before you use it.","vi":"Lắc kỹ chai trước khi dùng.","image_url":"https://images.pexels.com/photos/4812635/pexels-photo-4812635.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'well';
UPDATE preset_deck_cards SET ipa = '/bɪˈkəz/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bec/becau/because__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I stayed home because I had a bad cold.","vi":"Tôi ở nhà vì bị cảm nặng.","image_url":"https://images.pexels.com/photos/15508361/pexels-photo-15508361.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We took a taxi because it was raining heavily.","vi":"Chúng tôi đi taxi vì trời mưa to.","image_url":"https://images.pexels.com/photos/11891283/pexels-photo-11891283.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Because the store was closed, we went somewhere else.","vi":"Vì cửa hàng đã đóng cửa nên chúng tôi đi chỗ khác.","image_url":"https://images.pexels.com/photos/38514789/pexels-photo-38514789.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'because';
UPDATE preset_deck_cards SET ipa = '/kʌm/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/come_/come__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Can you come to my birthday party on Saturday?","vi":"Thứ Bảy bạn đến dự tiệc sinh nhật của tôi được không?","image_url":"https://images.pexels.com/photos/36071198/pexels-photo-36071198.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My father usually comes home from work at six.","vi":"Bố tôi thường đi làm về lúc sáu giờ.","image_url":"https://images.pexels.com/photos/8949354/pexels-photo-8949354.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Where does your new roommate come from?","vi":"Bạn cùng phòng mới của bạn đến từ đâu?","image_url":"https://images.pexels.com/photos/23224972/pexels-photo-23224972.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'come';
UPDATE preset_deck_cards SET ipa = '/wɜːrk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/work_/work__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"My mother works at a hospital in the city.","vi":"Mẹ tôi làm việc tại một bệnh viện trong thành phố.","image_url":"https://images.pexels.com/photos/18271838/pexels-photo-18271838.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I have to work late tonight to finish this report.","vi":"Tối nay tôi phải làm việc muộn để hoàn thành bản báo cáo này.","image_url":"https://images.pexels.com/photos/8370882/pexels-photo-8370882.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The printer in our office isn''t working again.","vi":"Máy in trong văn phòng chúng tôi lại không hoạt động rồi.","image_url":"https://images.pexels.com/photos/8297818/pexels-photo-8297818.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'work';
UPDATE preset_deck_cards SET ipa = '/juːz/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/use/use__/use__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Can I use your phone for a minute?","vi":"Cho tôi dùng điện thoại của bạn một lát được không?","image_url":"https://images.pexels.com/photos/4033675/pexels-photo-4033675.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We use this room for meetings and training.","vi":"Chúng tôi dùng phòng này để họp và đào tạo.","image_url":"https://images.pexels.com/photos/34221175/pexels-photo-34221175.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She used a knife to open the box.","vi":"Cô ấy dùng dao để mở chiếc hộp.","image_url":"https://images.pexels.com/photos/4506241/pexels-photo-4506241.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'use';
UPDATE preset_deck_cards SET ipa = '/lʊk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loo/look_/look__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Look at the beautiful sunset over the sea.","vi":"Nhìn hoàng hôn tuyệt đẹp trên biển kìa.","image_url":"https://images.pexels.com/photos/37200096/pexels-photo-37200096.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"He looked out of the window and saw the snow.","vi":"Anh ấy nhìn ra ngoài cửa sổ và thấy tuyết.","image_url":"https://images.pexels.com/photos/35356174/pexels-photo-35356174.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You look very tired after your long trip.","vi":"Trông bạn rất mệt sau chuyến đi dài.","image_url":"https://images.pexels.com/photos/30595796/pexels-photo-30595796.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'look';
UPDATE preset_deck_cards SET ipa = '/wɑːnt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wan/want_/want__us_1_rr.mp3', image_url = 'https://images.pexels.com/photos/5737622/pexels-photo-5737622.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Tim Mossholder","author_url":"https://www.pexels.com/@timmossholder","source_url":"https://www.pexels.com/photo/help-wanted-sign-on-glass-5737622/"}', examples = '[{"en":"I want to learn how to cook Italian food.","vi":"Tôi muốn học cách nấu món Ý.","image_url":"https://images.pexels.com/photos/6287488/pexels-photo-6287488.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What do you want for your birthday?","vi":"Bạn muốn được tặng gì vào dịp sinh nhật?","image_url":"https://images.pexels.com/photos/264771/pexels-photo-264771.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My parents wanted me to become a doctor.","vi":"Bố mẹ tôi đã muốn tôi trở thành bác sĩ.","image_url":"https://images.pexels.com/photos/7653094/pexels-photo-7653094.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'want';
UPDATE preset_deck_cards SET ipa = '/ɡɪv/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/giv/give_/give__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Please give this letter to your teacher.","vi":"Em hãy đưa lá thư này cho giáo viên của em nhé.","image_url":"https://images.pexels.com/photos/30945609/pexels-photo-30945609.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Could you give me some advice about buying a car?","vi":"Bạn có thể cho tôi vài lời khuyên về việc mua xe không?","image_url":"https://images.pexels.com/photos/6817009/pexels-photo-6817009.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My aunt gave me a watch for my birthday.","vi":"Dì tặng tôi một chiếc đồng hồ nhân dịp sinh nhật.","image_url":"https://images.pexels.com/photos/13018652/pexels-photo-13018652.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'give';
UPDATE preset_deck_cards SET ipa = '/fɜːrst/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/first/first__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I still remember my first day at school.","vi":"Tôi vẫn nhớ ngày đầu tiên đi học.","image_url":"https://images.pexels.com/photos/8421930/pexels-photo-8421930.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The first train leaves at five in the morning.","vi":"Chuyến tàu đầu tiên khởi hành lúc năm giờ sáng.","image_url":"https://images.pexels.com/photos/33816597/pexels-photo-33816597.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Take the first street on the left after the bank.","vi":"Rẽ vào con phố đầu tiên bên trái sau ngân hàng.","image_url":"https://images.pexels.com/photos/20414013/pexels-photo-20414013.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'first';
UPDATE preset_deck_cards SET ipa = '/nuː/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/new__/new__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I bought a new laptop for my studies.","vi":"Tôi mua một chiếc máy tính xách tay mới để học.","image_url":"https://images.pexels.com/photos/20432893/pexels-photo-20432893.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Our new neighbors are very friendly and helpful.","vi":"Hàng xóm mới của chúng tôi rất thân thiện và hay giúp đỡ.","image_url":"https://images.pexels.com/photos/6647031/pexels-photo-6647031.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Is it hard to make new friends in a big city?","vi":"Kết bạn mới ở thành phố lớn có khó không?","image_url":"https://images.pexels.com/photos/21853992/pexels-photo-21853992.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'new';
UPDATE preset_deck_cards SET ipa = '/weɪ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/way/way__/way__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"What is the best way to learn English?","vi":"Cách tốt nhất để học tiếng Anh là gì?","image_url":"https://images.pexels.com/photos/20875710/pexels-photo-20875710.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Excuse me, could you tell me the way to the station?","vi":"Xin lỗi, bạn có thể chỉ giúp tôi đường đến nhà ga không?","image_url":"https://images.pexels.com/photos/33629154/pexels-photo-33629154.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I bought some bread on my way home.","vi":"Tôi mua ít bánh mì trên đường về nhà.","image_url":"https://images.pexels.com/photos/7543099/pexels-photo-7543099.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'way';
UPDATE preset_deck_cards SET ipa = '/faɪnd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/find_/find__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I can''t find my car keys anywhere this morning.","vi":"Sáng nay tôi tìm khắp nơi mà không thấy chìa khóa xe.","image_url":"https://images.pexels.com/photos/2810140/pexels-photo-2810140.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She finally found a job at a local bank.","vi":"Cuối cùng cô ấy cũng tìm được việc ở một ngân hàng địa phương.","image_url":"https://images.pexels.com/photos/3869640/pexels-photo-3869640.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Most students find this exercise quite difficult.","vi":"Hầu hết học sinh thấy bài tập này khá khó.","image_url":"https://images.pexels.com/photos/37812834/pexels-photo-37812834.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'find';
UPDATE preset_deck_cards SET ipa = '/deɪ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/day/day__/day__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I drink two cups of coffee a day.","vi":"Tôi uống hai tách cà phê mỗi ngày.","image_url":"https://images.pexels.com/photos/35835482/pexels-photo-35835482.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We spent the whole day at the beach.","vi":"Chúng tôi ở bãi biển cả ngày.","image_url":"https://images.pexels.com/photos/29293836/pexels-photo-29293836.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My father works during the day and studies at night.","vi":"Bố tôi làm việc ban ngày và đi học vào buổi tối.","image_url":"https://images.pexels.com/photos/9345689/pexels-photo-9345689.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'day';
UPDATE preset_deck_cards SET ipa = '/θɪŋ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thing/thing__us_1.mp3', image_url = 'https://images.pexels.com/photos/6353770/pexels-photo-6353770.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Anete Lusina","author_url":"https://www.pexels.com/@anete-lusina","source_url":"https://www.pexels.com/photo/textbook-with-message-on-hardcover-against-window-6353770/"}', examples = '[{"en":"Put your things in the bag before we leave.","vi":"Cất đồ của bạn vào túi trước khi chúng ta đi nhé.","image_url":"https://images.pexels.com/photos/9185809/pexels-photo-9185809.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The most important thing is your health.","vi":"Điều quan trọng nhất là sức khỏe của bạn.","image_url":"https://images.pexels.com/photos/5080100/pexels-photo-5080100.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I have a lot of things to do today.","vi":"Hôm nay tôi có rất nhiều việc phải làm.","image_url":"https://images.pexels.com/photos/7888981/pexels-photo-7888981.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'thing';
UPDATE preset_deck_cards SET ipa = '/niːd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nee/need_/need__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I need to buy some milk on the way home.","vi":"Tôi cần mua ít sữa trên đường về nhà.","image_url":"https://images.pexels.com/photos/8718885/pexels-photo-8718885.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Do you need any help with those bags?","vi":"Bạn có cần giúp mang mấy cái túi đó không?","image_url":"https://images.pexels.com/photos/9531993/pexels-photo-9531993.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Plants need water and sunlight to grow.","vi":"Cây cần nước và ánh nắng để phát triển.","image_url":"https://images.pexels.com/photos/4894621/pexels-photo-4894621.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'need';
UPDATE preset_deck_cards SET ipa = '/raɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rig/right/right__us_1.mp3', image_url = 'https://images.pexels.com/photos/8834285/pexels-photo-8834285.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"cottonbro CG studio","author_url":"https://www.pexels.com/@cottonbro-cg-studio","source_url":"https://www.pexels.com/photo/an-animation-of-pointing-finger-on-a-black-background-8834285/"}', examples = '[{"en":"You''re right, the meeting starts at ten, not nine.","vi":"Bạn nói đúng, cuộc họp bắt đầu lúc mười giờ chứ không phải chín giờ.","image_url":"https://images.pexels.com/photos/30073743/pexels-photo-30073743.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Is this the right bus for the city center?","vi":"Đây có đúng là xe buýt đi vào trung tâm thành phố không?","image_url":"https://images.pexels.com/photos/26807015/pexels-photo-26807015.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She broke her right arm while playing basketball.","vi":"Cô ấy bị gãy tay phải khi chơi bóng rổ.","image_url":"https://images.pexels.com/photos/10396727/pexels-photo-10396727.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-01' AND english = 'right';
-- ngsl-1-02
UPDATE preset_deck_cards SET ipa = '/bæk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bac/back_/back__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I''ll be back in about ten minutes.","vi":"Khoảng mười phút nữa tôi sẽ quay lại."},{"en":"She looked back and waved goodbye to us.","vi":"Cô ấy ngoảnh lại và vẫy tay chào tạm biệt chúng tôi."},{"en":"What time did you come back last night?","vi":"Tối qua mấy giờ bạn mới quay về?"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'back';
UPDATE preset_deck_cards SET ipa = '/miːn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/mean_/mean__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"What does this word mean in Vietnamese?","vi":"Từ này trong tiếng Việt có nghĩa là gì?"},{"en":"I know what you mean, but I don''t agree.","vi":"Tôi hiểu ý bạn, nhưng tôi không đồng ý."},{"en":"Sorry, I didn''t mean to wake you up.","vi":"Xin lỗi, tôi không cố ý đánh thức bạn."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'mean';
UPDATE preset_deck_cards SET ipa = '/ˈiːvn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/even_/even__us_1.mp3', image_url = 'https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Max Kladitin","author_url":"https://www.pexels.com/@max-kladitin-456997122","source_url":"https://www.pexels.com/photo/historic-brick-architecture-in-berlin-street-scene-36937024/"}', examples = '[{"en":"Even my little brother can use this phone.","vi":"Ngay cả em trai tôi cũng dùng được chiếc điện thoại này.","image_url":"https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"He didn''t even say goodbye before he left.","vi":"Anh ấy thậm chí còn không chào tạm biệt trước khi đi.","image_url":"https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The second test was even harder than the first one.","vi":"Bài kiểm tra thứ hai còn khó hơn bài đầu tiên.","image_url":"https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'even';
UPDATE preset_deck_cards SET ipa = '/læst/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/las/last_/last__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"This is the last bus to the city tonight.","vi":"Đây là chuyến xe buýt cuối cùng vào thành phố tối nay."},{"en":"We went to the beach last weekend.","vi":"Cuối tuần trước chúng tôi đã đi biển."},{"en":"When was the last time you saw a doctor?","vi":"Lần cuối bạn đi khám bác sĩ là khi nào?"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'last';
UPDATE preset_deck_cards SET ipa = '/tʃaɪld/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/child/child__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Every child in the class got a small gift.","vi":"Mọi đứa trẻ trong lớp đều nhận được một món quà nhỏ.","image_url":"https://images.pexels.com/photos/14831686/pexels-photo-14831686.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"They have three children, two boys and a girl.","vi":"Họ có ba người con, hai trai một gái."},{"en":"As a child, I spent every summer at my grandmother''s house.","vi":"Hồi nhỏ, mùa hè nào tôi cũng ở nhà bà."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'child';
UPDATE preset_deck_cards SET ipa = '/tel/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tel/tell_/tell__us_1.mp3', image_url = 'https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Brett Jordan","author_url":"https://www.pexels.com/@brettjordan","source_url":"https://www.pexels.com/photo/a-told-you-so-quote-on-wooden-scrabble-pieces-10767940/"}', examples = '[{"en":"Can you tell me where the train station is?","vi":"Bạn có thể cho tôi biết nhà ga ở đâu không?","image_url":"https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My grandfather told us a funny story last night.","vi":"Tối qua ông tôi kể cho chúng tôi nghe một câu chuyện vui.","image_url":"https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The teacher told the students to turn off their phones.","vi":"Cô giáo bảo học sinh tắt điện thoại.","image_url":"https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'tell';
UPDATE preset_deck_cards SET ipa = '/ˈriːəli/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reall/really__us_3_rr.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Do you really want to quit your job?","vi":"Bạn thật sự muốn nghỉ việc à?"},{"en":"We had a really good time at the party.","vi":"Chúng tôi đã rất vui ở bữa tiệc."},{"en":"I''m really sorry that I forgot your birthday.","vi":"Tôi thực sự xin lỗi vì đã quên sinh nhật của bạn."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'really';
UPDATE preset_deck_cards SET ipa = '/kɔːl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cal/call_/call__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I''ll call you when I get home.","vi":"Khi về đến nhà tôi sẽ gọi cho bạn."},{"en":"Can you call me back in an hour?","vi":"Một tiếng nữa bạn gọi lại cho tôi được không?","image_url":"https://images.pexels.com/photos/41372/call-communication-contact-face-41372.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What do you call this dish in English?","vi":"Món này tiếng Anh gọi là gì?"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'call';
UPDATE preset_deck_cards SET ipa = '/bɪˈfɔːr/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bef/befor/before__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"We arrived just before the movie started.","vi":"Chúng tôi đến ngay trước khi phim bắt đầu."},{"en":"Always wash your hands before you eat.","vi":"Hãy luôn rửa tay trước khi ăn."},{"en":"I have never seen this movie before.","vi":"Tôi chưa bao giờ xem bộ phim này trước đây."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'before';
UPDATE preset_deck_cards SET ipa = '/ˈkʌmpəni/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/company__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"My sister works for a small software company.","vi":"Chị tôi làm việc cho một công ty phần mềm nhỏ."},{"en":"The company hired twenty new workers this year.","vi":"Năm nay công ty đã tuyển hai mươi nhân viên mới."},{"en":"I enjoy her company because she always makes me laugh.","vi":"Tôi thích ở bên cô ấy vì cô ấy luôn làm tôi cười.","image_url":"https://images.pexels.com/photos/4307787/pexels-photo-4307787.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'company';
UPDATE preset_deck_cards SET ipa = '/ʃəʊ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/show_/show__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"She showed us photos from her trip to Japan.","vi":"Cô ấy cho chúng tôi xem ảnh chuyến đi Nhật Bản."},{"en":"Can you show me how to use this machine?","vi":"Bạn chỉ tôi cách dùng cái máy này được không?"},{"en":"The results show that more people are working from home.","vi":"Kết quả cho thấy có nhiều người làm việc tại nhà hơn."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'show';
UPDATE preset_deck_cards SET ipa = '/laɪf/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lif/life_/life__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Life in the city is busy and expensive.","vi":"Cuộc sống ở thành phố bận rộn và đắt đỏ."},{"en":"He spent his whole life in this small village.","vi":"Ông ấy sống cả đời ở ngôi làng nhỏ này."},{"en":"Scientists are still looking for life on other planets.","vi":"Các nhà khoa học vẫn đang tìm kiếm sự sống trên các hành tinh khác."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'life';
UPDATE preset_deck_cards SET ipa = '/mæn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/man__/man__us_1.mp3', image_url = 'https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Ali Durmuş Cevlan","author_url":"https://www.pexels.com/@ali-durmus-cevlan-518867579","source_url":"https://www.pexels.com/photo/portrait-of-elderly-man-in-aksehir-turkiye-39373268/"}', examples = '[{"en":"A man in a blue jacket asked me for directions.","vi":"Một người đàn ông mặc áo khoác xanh hỏi đường tôi.","image_url":"https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The old man lives alone with his cat.","vi":"Ông cụ sống một mình với con mèo.","image_url":"https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Both men and women can apply for this job.","vi":"Cả nam và nữ đều có thể ứng tuyển công việc này.","image_url":"https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'man';
UPDATE preset_deck_cards SET ipa = '/tʃeɪndʒ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chang/change__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"You haven''t changed at all since high school.","vi":"Bạn chẳng thay đổi gì cả kể từ hồi cấp ba."},{"en":"We changed trains twice on the way to the coast.","vi":"Chúng tôi đã đổi tàu hai lần trên đường ra biển."},{"en":"Let me change my clothes before we go out.","vi":"Để tôi thay quần áo trước khi chúng ta ra ngoài."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'change';
UPDATE preset_deck_cards SET ipa = '/pleɪs/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/place/place__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"This is a great place to have lunch.","vi":"Đây là một chỗ ăn trưa rất tuyệt.","image_url":"https://images.pexels.com/photos/1545400/pexels-photo-1545400.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Let''s meet at my place after work.","vi":"Tan làm mình gặp nhau ở nhà tôi nhé."},{"en":"She finished in second place in the race.","vi":"Cô ấy về đích ở vị trí thứ hai trong cuộc đua."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'place';
UPDATE preset_deck_cards SET ipa = '/lɔːŋ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lon/long_/long__us_8.mp3', image_url = 'https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"German Suarez","author_url":"https://www.pexels.com/@german-suarez-2985952","source_url":"https://www.pexels.com/photo/elegant-borzoi-dog-lying-outdoors-in-park-39525018/"}', examples = '[{"en":"My sister has long black hair like our mother.","vi":"Chị tôi có mái tóc đen dài giống mẹ.","image_url":"https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It was a long day, so I went to bed early.","vi":"Hôm đó là một ngày dài nên tôi đi ngủ sớm.","image_url":"https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"How long does it take to get to the airport?","vi":"Đi đến sân bay mất bao lâu?","image_url":"https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'long';
UPDATE preset_deck_cards SET ipa = '/bɪˈtwiːn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bet/betwe/between__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The bank is between the post office and the school.","vi":"Ngân hàng nằm giữa bưu điện và trường học."},{"en":"I usually have a snack between lunch and dinner.","vi":"Tôi thường ăn vặt giữa bữa trưa và bữa tối."},{"en":"What''s the difference between these two phones?","vi":"Hai chiếc điện thoại này khác nhau ở điểm nào?","image_url":"https://images.pexels.com/photos/33453407/pexels-photo-33453407.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'between';
UPDATE preset_deck_cards SET ipa = '/fiːl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/feel_/feel__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I feel tired after a long day at work.","vi":"Tôi thấy mệt sau một ngày dài làm việc."},{"en":"How do you feel about moving to a new city?","vi":"Bạn cảm thấy thế nào về việc chuyển đến một thành phố mới?"},{"en":"The baby''s skin felt soft and warm.","vi":"Da em bé sờ vào thấy mềm và ấm."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'feel';
UPDATE preset_deck_cards SET ipa = '/stɪl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/still/still__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Are you still living in the same apartment?","vi":"Bạn vẫn sống ở căn hộ cũ à?"},{"en":"It''s almost noon, and he is still asleep.","vi":"Gần trưa rồi mà anh ấy vẫn còn ngủ."},{"en":"I studied hard, but I still failed the test.","vi":"Tôi đã học chăm chỉ nhưng vẫn trượt bài kiểm tra."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'still';
UPDATE preset_deck_cards SET ipa = '/ˈprɑːbləm/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/probl/problem__us_1.mp3', image_url = 'https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Ann H","author_url":"https://www.pexels.com/@ann-h-45017","source_url":"https://www.pexels.com/photo/yellow-letter-tiles-1888016/"}', examples = '[{"en":"We''re having a problem with the kitchen sink again.","vi":"Bồn rửa trong bếp nhà chúng tôi lại bị trục trặc.","image_url":"https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Talking to a friend can help you solve a problem.","vi":"Trò chuyện với bạn bè có thể giúp bạn giải quyết vấn đề.","image_url":"https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"No problem, I can pick you up from the station.","vi":"Không sao, tôi có thể đón bạn ở nhà ga.","image_url":"https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'problem';
UPDATE preset_deck_cards SET ipa = '/raɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wri/write/write__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Please write your name at the top of the page.","vi":"Hãy viết tên của bạn ở đầu trang."},{"en":"She wrote a long letter to her grandparents.","vi":"Cô ấy đã viết một lá thư dài cho ông bà."},{"en":"I have to write a report for my boss by Friday.","vi":"Tôi phải viết báo cáo cho sếp trước thứ Sáu."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'write';
UPDATE preset_deck_cards SET ipa = '/seɪm/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sam/same_/same__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"We were born in the same year.","vi":"Chúng tôi sinh cùng một năm.","image_url":"https://images.pexels.com/photos/6224827/pexels-photo-6224827.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Your bag looks the same as mine.","vi":"Túi của bạn trông giống hệt túi của tôi."},{"en":"He orders the same thing every time we eat here.","vi":"Lần nào ăn ở đây anh ấy cũng gọi đúng một món đó."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'same';
UPDATE preset_deck_cards SET ipa = '/lɑːt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lot/lot__/lot__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"There were a lot of people at the market today.","vi":"Hôm nay ở chợ có rất đông người."},{"en":"Thanks a lot for helping me move.","vi":"Cảm ơn bạn nhiều vì đã giúp tôi chuyển nhà."},{"en":"She has changed a lot since last year.","vi":"Cô ấy đã thay đổi nhiều kể từ năm ngoái."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'lot';
UPDATE preset_deck_cards SET ipa = '/ɡreɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/great/great__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"We had a great time at the beach.","vi":"Chúng tôi đã có khoảng thời gian tuyệt vời ở biển."},{"en":"Your new apartment looks great with all those plants.","vi":"Căn hộ mới của bạn trông thật tuyệt với mấy chậu cây đó.","image_url":"https://images.pexels.com/photos/5825371/pexels-photo-5825371.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Our first charity event was a great success.","vi":"Sự kiện từ thiện đầu tiên của chúng tôi đã thành công lớn."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'great';
UPDATE preset_deck_cards SET ipa = '/traɪ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/try/try__/try__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"I''ll try to finish the report by tonight.","vi":"Tôi sẽ cố gắng hoàn thành báo cáo trước tối nay."},{"en":"Have you ever tried Vietnamese iced coffee?","vi":"Bạn đã bao giờ thử cà phê đá Việt Nam chưa?"},{"en":"Can I try on these shoes in a smaller size?","vi":"Tôi có thể thử đôi giày này cỡ nhỏ hơn không?"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'try';
UPDATE preset_deck_cards SET ipa = '/liːv/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leave/leave__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"What time does your train leave in the morning?","vi":"Buổi sáng tàu của bạn khởi hành lúc mấy giờ?"},{"en":"She leaves home at seven every morning.","vi":"Sáng nào cô ấy cũng ra khỏi nhà lúc bảy giờ."},{"en":"I left my umbrella on the bus.","vi":"Tôi để quên ô trên xe buýt.","image_url":"https://images.pexels.com/photos/19116710/pexels-photo-19116710.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'leave';
UPDATE preset_deck_cards SET ipa = '/ˈnʌmbər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/num/numbe/number__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Could you give me your phone number, please?","vi":"Bạn cho tôi xin số điện thoại được không?"},{"en":"The number of students in our class has grown.","vi":"Số lượng học sinh trong lớp chúng tôi đã tăng lên."},{"en":"A large number of tourists visit the old town every summer.","vi":"Mỗi mùa hè có rất nhiều du khách đến thăm phố cổ.","image_url":"https://images.pexels.com/photos/34128969/pexels-photo-34128969.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'number';
UPDATE preset_deck_cards SET ipa = '/pɑːrt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/part_/part__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The best part of the trip was the food.","vi":"Phần tuyệt nhất của chuyến đi là đồ ăn."},{"en":"My car needs a new part, so it''s at the garage.","vi":"Xe tôi cần thay một bộ phận mới nên đang nằm ở gara."},{"en":"She got a small part in the school play.","vi":"Cô ấy được nhận một vai nhỏ trong vở kịch của trường."}]' WHERE deck_code = 'ngsl-1-02' AND english = 'part';
UPDATE preset_deck_cards SET ipa = '/pɔɪnt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poi/point/point__us_3.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Our team won the game by two points.","vi":"Đội của chúng tôi thắng trận với cách biệt hai điểm.","image_url":"https://images.pexels.com/photos/4468119/pexels-photo-4468119.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You make a good point about the cost of the trip.","vi":"Bạn đã nêu ra một ý hay về chi phí của chuyến đi.","image_url":"https://images.pexels.com/photos/4468119/pexels-photo-4468119.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What''s the point of buying a car if you never drive?","vi":"Mua ô tô thì có ích gì nếu bạn chẳng bao giờ lái?","image_url":"https://images.pexels.com/photos/4468119/pexels-photo-4468119.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'point';
UPDATE preset_deck_cards SET ipa = '/ˈlɪtl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/littl/little__us_4.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"We live in a little house near the river.","vi":"Chúng tôi sống trong một ngôi nhà nhỏ gần sông."},{"en":"My little sister is starting school this year.","vi":"Em gái tôi năm nay bắt đầu đi học."},{"en":"Could you speak a little more slowly, please?","vi":"Bạn nói chậm hơn một chút được không?"}]' WHERE deck_code = 'ngsl-1-02' AND english = 'little';
