UPDATE preset_deck_cards SET ipa = '/ˈænəlaɪz/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analy/analyse__us_2.mp3', image_url = 'https://images.pexels.com/photos/8442898/pexels-photo-8442898.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Pavel Danilyuk","author_url":"https://www.pexels.com/@pavel-danilyuk","source_url":"https://www.pexels.com/photo/close-up-photo-of-a-microscope-with-glass-slide-8442898/"}', examples = '[{"en":"Researchers analysed data from more than two thousand patients.","vi":"Các nhà nghiên cứu đã phân tích dữ liệu từ hơn hai nghìn bệnh nhân.","image_url":"https://images.pexels.com/photos/7578799/pexels-photo-7578799.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Before writing the report, we need to analyse the survey results carefully.","vi":"Trước khi viết báo cáo, chúng ta cần phân tích kỹ kết quả khảo sát.","image_url":"https://images.pexels.com/photos/669610/pexels-photo-669610.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The team is still analysing why sales fell last quarter.","vi":"Nhóm vẫn đang phân tích lý do doanh số giảm trong quý trước.","image_url":"https://images.pexels.com/photos/6016350/pexels-photo-6016350.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'analyse';
UPDATE preset_deck_cards SET ipa = '/əˈprəʊtʃ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approach__us_1.mp3', image_url = 'https://images.pexels.com/photos/7688440/pexels-photo-7688440.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Kindel Media","author_url":"https://www.pexels.com/@kindelmedia","source_url":"https://www.pexels.com/photo/person-s-hand-on-white-paper-7688440/"}', examples = '[{"en":"The school has taken a new approach to teaching reading.","vi":"Nhà trường đã áp dụng một cách tiếp cận mới trong việc dạy đọc.","image_url":"https://images.pexels.com/photos/8499566/pexels-photo-8499566.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This approach works well for small businesses but not for large ones.","vi":"Phương pháp này hiệu quả với doanh nghiệp nhỏ nhưng không hiệu quả với doanh nghiệp lớn.","image_url":"https://images.pexels.com/photos/36714292/pexels-photo-36714292.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Scientists are testing a different approach to treating the disease.","vi":"Các nhà khoa học đang thử nghiệm một phương pháp khác để điều trị căn bệnh này.","image_url":"https://images.pexels.com/photos/4149047/pexels-photo-4149047.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'approach';
UPDATE preset_deck_cards SET ipa = '/ˈeriə/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/are/area_/area__us_2.mp3', image_url = 'https://images.pexels.com/photos/19061849/pexels-photo-19061849.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"K","author_url":"https://www.pexels.com/@kelly","source_url":"https://www.pexels.com/photo/aerial-view-of-an-overpass-over-railway-tracks-19061849/"}', examples = '[{"en":"Many families have moved out of the city into rural areas.","vi":"Nhiều gia đình đã rời thành phố để chuyển về các vùng nông thôn.","image_url":"https://images.pexels.com/photos/16644802/pexels-photo-16644802.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Her main area of research is language development in children.","vi":"Lĩnh vực nghiên cứu chính của cô ấy là sự phát triển ngôn ngữ ở trẻ em.","image_url":"https://images.pexels.com/photos/8087867/pexels-photo-8087867.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The park covers an area of about fifty square kilometers.","vi":"Công viên có diện tích khoảng năm mươi ki-lô-mét vuông.","image_url":"https://images.pexels.com/photos/18368795/pexels-photo-18368795.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'area';
UPDATE preset_deck_cards SET ipa = '/əˈses/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asses/assess__us_2.mp3', image_url = 'https://images.pexels.com/photos/8654753/pexels-photo-8654753.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Mikhail Nilov","author_url":"https://www.pexels.com/@mikhail-nilov","source_url":"https://www.pexels.com/photo/close-up-of-man-looking-at-a-document-with-an-autism-test-8654753/"}', examples = '[{"en":"Teachers assess students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ.","image_url":"https://images.pexels.com/photos/8363162/pexels-photo-8363162.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It is too early to assess the impact of the new policy.","vi":"Còn quá sớm để đánh giá tác động của chính sách mới.","image_url":"https://images.pexels.com/photos/10341357/pexels-photo-10341357.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Experts were called in to assess the damage after the flood.","vi":"Các chuyên gia được mời đến để đánh giá thiệt hại sau trận lũ.","image_url":"https://images.pexels.com/photos/14000741/pexels-photo-14000741.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'assess';
UPDATE preset_deck_cards SET ipa = '/əˈsuːm/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assum/assume__us_2.mp3', image_url = 'https://images.pexels.com/photos/8932407/pexels-photo-8932407.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Brett Sayles","author_url":"https://www.pexels.com/@brett-sayles","source_url":"https://www.pexels.com/photo/close-up-of-a-sentence-on-a-letter-board-8932407/"}', examples = '[{"en":"Many people assume that older workers cannot learn new skills.","vi":"Nhiều người cho rằng người lao động lớn tuổi không thể học kỹ năng mới.","image_url":"https://images.pexels.com/photos/7983575/pexels-photo-7983575.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"For this calculation, we assume that prices will stay the same.","vi":"Trong phép tính này, chúng tôi giả định rằng giá cả sẽ giữ nguyên.","image_url":"https://images.pexels.com/photos/262470/pexels-photo-262470.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She will assume responsibility for the project next month.","vi":"Tháng sau cô ấy sẽ đảm nhận trách nhiệm về dự án.","image_url":"https://images.pexels.com/photos/6732207/pexels-photo-6732207.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'assume';
UPDATE preset_deck_cards SET ipa = '/əˈθɔːrəti/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autho/authority__us_1_rr.mp3', image_url = 'https://images.pexels.com/photos/684387/pexels-photo-684387.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Lukas Blazek","author_url":"https://www.pexels.com/@goumbik","source_url":"https://www.pexels.com/photo/close-up-photo-of-a-person-wearing-suit-jacket-684387/"}', examples = '[{"en":"Local authorities have closed the road for repairs.","vi":"Chính quyền địa phương đã đóng con đường để sửa chữa.","image_url":"https://images.pexels.com/photos/4134380/pexels-photo-4134380.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Only the manager has the authority to approve payments.","vi":"Chỉ người quản lý mới có thẩm quyền phê duyệt các khoản thanh toán.","image_url":"https://images.pexels.com/photos/7821463/pexels-photo-7821463.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She is a leading authority on climate change.","vi":"Bà ấy là một chuyên gia hàng đầu về biến đổi khí hậu.","image_url":"https://images.pexels.com/photos/11939228/pexels-photo-11939228.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'authority';
UPDATE preset_deck_cards SET ipa = '/əˈveɪləbl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ava/avail/available__us_1.mp3', image_url = 'https://images.pexels.com/photos/13257111/pexels-photo-13257111.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Quang Viet Nguyen","author_url":"https://www.pexels.com/@quang-viet-nguyen-107013384","source_url":"https://www.pexels.com/photo/grayscale-photo-of-a-wristwatch-13257111/"}', examples = '[{"en":"The full report is publicly available on the company website.","vi":"Bản báo cáo đầy đủ được công khai trên trang web của công ty.","image_url":"https://images.pexels.com/photos/5918191/pexels-photo-5918191.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Free parking is available for all visitors.","vi":"Có chỗ đỗ xe miễn phí cho tất cả khách đến thăm.","image_url":"https://images.pexels.com/photos/20018335/pexels-photo-20018335.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Is the manager available for a meeting this afternoon?","vi":"Chiều nay người quản lý có rảnh để họp không?","image_url":"https://images.pexels.com/photos/7504810/pexels-photo-7504810.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'available';
UPDATE preset_deck_cards SET ipa = '/ˈbenɪfɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/benef/benefit__us_1.mp3', image_url = 'https://images.pexels.com/photos/1172019/pexels-photo-1172019.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Lisa Fotios","author_url":"https://www.pexels.com/@fotios-photos","source_url":"https://www.pexels.com/photo/strawberries-and-measuring-tape-1172019/"}', examples = '[{"en":"Regular exercise has many benefits for mental health.","vi":"Tập thể dục thường xuyên có nhiều lợi ích cho sức khỏe tinh thần.","image_url":"https://images.pexels.com/photos/36715612/pexels-photo-36715612.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The new system will bring clear benefits to small farmers.","vi":"Hệ thống mới sẽ mang lại lợi ích rõ rệt cho các nông hộ nhỏ.","image_url":"https://images.pexels.com/photos/17765487/pexels-photo-17765487.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"People who lose their jobs may apply for unemployment benefits.","vi":"Những người mất việc có thể nộp đơn xin trợ cấp thất nghiệp.","image_url":"https://images.pexels.com/photos/9830115/pexels-photo-9830115.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'benefit';
UPDATE preset_deck_cards SET ipa = '/ˈkɑːnsept/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcept__us_1.mp3', image_url = 'https://images.pexels.com/photos/7257156/pexels-photo-7257156.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Anete Lusina","author_url":"https://www.pexels.com/@anete-lusina","source_url":"https://www.pexels.com/photo/project-on-papers-7257156/"}', examples = '[{"en":"Young children find the concept of time difficult to understand.","vi":"Trẻ nhỏ thấy khái niệm thời gian rất khó hiểu.","image_url":"https://images.pexels.com/photos/5303503/pexels-photo-5303503.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This chapter introduces the basic concepts of economics.","vi":"Chương này giới thiệu các khái niệm cơ bản của kinh tế học.","image_url":"https://images.pexels.com/photos/7873576/pexels-photo-7873576.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The designers came up with a fresh concept for the new store.","vi":"Các nhà thiết kế đã nghĩ ra một ý tưởng mới mẻ cho cửa hàng mới.","image_url":"https://images.pexels.com/photos/39364652/pexels-photo-39364652.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'concept';
UPDATE preset_deck_cards SET ipa = '/kənˈsɪst/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsist__us_1.mp3', image_url = 'https://images.pexels.com/photos/39441321/pexels-photo-39441321.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Jahra Tasfia Reza","author_url":"https://www.pexels.com/@jahratreza","source_url":"https://www.pexels.com/photo/pouring-syrup-into-spoon-outdoors-closeup-39441321/"}', examples = '[{"en":"The committee consists of twelve members from different departments.","vi":"Ủy ban gồm mười hai thành viên đến từ các phòng ban khác nhau.","image_url":"https://images.pexels.com/photos/32870073/pexels-photo-32870073.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The course consists of ten lectures and three written assignments.","vi":"Khóa học gồm mười bài giảng và ba bài tập viết.","image_url":"https://images.pexels.com/photos/7092339/pexels-photo-7092339.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Their diet consisted mainly of fish and rice.","vi":"Chế độ ăn của họ chủ yếu gồm cá và cơm.","image_url":"https://images.pexels.com/photos/36855860/pexels-photo-36855860.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'consist';
UPDATE preset_deck_cards SET ipa = '/ˈkɑːnstɪtuːt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstitute__us_1.mp3', image_url = 'https://images.pexels.com/photos/8850742/pexels-photo-8850742.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Tara Winstead","author_url":"https://www.pexels.com/@tara-winstead","source_url":"https://www.pexels.com/photo/close-up-shot-of-a-law-book-8850742/"}', examples = '[{"en":"Women constitute nearly half of the country''s workforce.","vi":"Phụ nữ chiếm gần một nửa lực lượng lao động của cả nước.","image_url":"https://images.pexels.com/photos/4770610/pexels-photo-4770610.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Such behavior may constitute a serious threat to public safety.","vi":"Hành vi như vậy có thể được coi là mối đe dọa nghiêm trọng đối với an toàn công cộng.","image_url":"https://images.pexels.com/photos/38486967/pexels-photo-38486967.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"These ten principles constitute the basis of the new law.","vi":"Mười nguyên tắc này tạo thành nền tảng của bộ luật mới.","image_url":"https://images.pexels.com/photos/8850737/pexels-photo-8850737.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'constitute';
UPDATE preset_deck_cards SET ipa = '/ˈkɑːntekst/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontext__us_1.mp3', image_url = 'https://images.pexels.com/photos/16943785/pexels-photo-16943785.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Brett Jordan","author_url":"https://www.pexels.com/@brettjordan","source_url":"https://www.pexels.com/photo/atonement-sign-out-of-scrabble-tiles-16943785/"}', examples = '[{"en":"These events must be understood in their historical context.","vi":"Những sự kiện này phải được hiểu trong bối cảnh lịch sử của chúng.","image_url":"https://images.pexels.com/photos/36289771/pexels-photo-36289771.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You can often guess the meaning of a word from the context.","vi":"Bạn thường có thể đoán nghĩa của một từ dựa vào ngữ cảnh.","image_url":"https://images.pexels.com/photos/159581/dictionary-reference-book-learning-meaning-159581.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The writer complained that her comments had been taken out of context.","vi":"Nhà văn phàn nàn rằng những nhận xét của bà đã bị trích dẫn tách khỏi ngữ cảnh.","image_url":"https://images.pexels.com/photos/684319/pexels-photo-684319.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'context';
UPDATE preset_deck_cards SET ipa = '/ˈkɑːntrækt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontract__us_1.mp3', image_url = 'https://images.pexels.com/photos/7841818/pexels-photo-7841818.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"RDNE Stock project","author_url":"https://www.pexels.com/@rdne","source_url":"https://www.pexels.com/photo/close-up-shot-of-a-document-on-a-wooden-table-7841818/"}', examples = '[{"en":"Both companies signed a three-year contract last week.","vi":"Tuần trước, hai công ty đã ký một hợp đồng ba năm.","image_url":"https://images.pexels.com/photos/7841410/pexels-photo-7841410.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Many young people now work on short-term contracts.","vi":"Nhiều người trẻ hiện nay làm việc theo hợp đồng ngắn hạn.","image_url":"https://images.pexels.com/photos/8962686/pexels-photo-8962686.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"If the supplier breaks the contract, we can ask for our money back.","vi":"Nếu nhà cung cấp vi phạm hợp đồng, chúng ta có thể yêu cầu hoàn tiền.","image_url":"https://images.pexels.com/photos/38783384/pexels-photo-38783384.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'contract';
UPDATE preset_deck_cards SET ipa = '/kriˈeɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/create__us_1.mp3', image_url = 'https://images.pexels.com/photos/4116518/pexels-photo-4116518.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Magda Ehlers","author_url":"https://www.pexels.com/@magda-ehlers-pexels","source_url":"https://www.pexels.com/photo/create-message-4116518/"}', examples = '[{"en":"The new factory will create around five hundred jobs.","vi":"Nhà máy mới sẽ tạo ra khoảng năm trăm việc làm.","image_url":"https://images.pexels.com/photos/29141369/pexels-photo-29141369.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The students created a short video about saving water.","vi":"Các sinh viên đã tạo một video ngắn về việc tiết kiệm nước.","image_url":"https://images.pexels.com/photos/6990575/pexels-photo-6990575.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Poor planning can create serious problems later on.","vi":"Lập kế hoạch kém có thể gây ra những vấn đề nghiêm trọng về sau.","image_url":"https://images.pexels.com/photos/3771045/pexels-photo-3771045.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'create';
UPDATE preset_deck_cards SET ipa = '/ˈdeɪtə/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/data_/data__us_3_rr.mp3', image_url = 'https://images.pexels.com/photos/17489163/pexels-photo-17489163.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"panumas nikhomkhai","author_url":"https://www.pexels.com/@cookiecutter","source_url":"https://www.pexels.com/photo/computer-server-in-data-center-room-17489163/"}', examples = '[{"en":"The data show a clear link between sleep and memory.","vi":"Dữ liệu cho thấy mối liên hệ rõ ràng giữa giấc ngủ và trí nhớ.","image_url":"https://images.pexels.com/photos/8919892/pexels-photo-8919892.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We collected data from over three hundred schools.","vi":"Chúng tôi đã thu thập dữ liệu từ hơn ba trăm trường học.","image_url":"https://images.pexels.com/photos/6368842/pexels-photo-6368842.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The latest data on household spending will be published next week.","vi":"Số liệu mới nhất về chi tiêu hộ gia đình sẽ được công bố vào tuần tới.","image_url":"https://images.pexels.com/photos/4959907/pexels-photo-4959907.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'data';
UPDATE preset_deck_cards SET ipa = '/dɪˈfaɪn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/define__us_2.mp3', image_url = 'https://images.pexels.com/photos/18002046/pexels-photo-18002046.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Farhad Irani","author_url":"https://www.pexels.com/@farhadirani","source_url":"https://www.pexels.com/photo/muscular-model-posing-by-window-18002046/"}', examples = '[{"en":"It is hard to define exactly what makes a good teacher.","vi":"Rất khó để định nghĩa chính xác thế nào là một giáo viên giỏi.","image_url":"https://images.pexels.com/photos/8197497/pexels-photo-8197497.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"In this study, poverty is defined as living on less than two dollars a day.","vi":"Trong nghiên cứu này, nghèo đói được định nghĩa là sống với dưới hai đô la mỗi ngày.","image_url":"https://images.pexels.com/photos/8719574/pexels-photo-8719574.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The contract clearly defines the duties of each partner.","vi":"Hợp đồng xác định rõ nghĩa vụ của mỗi bên.","image_url":"https://images.pexels.com/photos/5520297/pexels-photo-5520297.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'define';
UPDATE preset_deck_cards SET ipa = '/dɪˈraɪv/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/der/deriv/derive__us_1.mp3', image_url = 'https://images.pexels.com/photos/33367162/pexels-photo-33367162.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"César O''neill","author_url":"https://www.pexels.com/@cesar-o-neill-26650613","source_url":"https://www.pexels.com/photo/assortment-of-natural-clays-and-minerals-on-wooden-plates-33367162/"}', examples = '[{"en":"Many English words are derived from Latin or Greek.","vi":"Nhiều từ tiếng Anh có nguồn gốc từ tiếng La-tinh hoặc tiếng Hy Lạp.","image_url":"https://images.pexels.com/photos/256417/pexels-photo-256417.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The results were derived from a survey of 500 teachers.","vi":"Các kết quả này được rút ra từ một cuộc khảo sát 500 giáo viên.","image_url":"https://images.pexels.com/photos/6684373/pexels-photo-6684373.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Older people often derive great pleasure from gardening.","vi":"Người lớn tuổi thường tìm thấy niềm vui lớn từ việc làm vườn.","image_url":"https://images.pexels.com/photos/6787679/pexels-photo-6787679.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'derive';
UPDATE preset_deck_cards SET ipa = '/dɪˈstrɪbjuːt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distr/distribute__us_1_rr.mp3', image_url = 'https://images.pexels.com/photos/6699395/pexels-photo-6699395.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Gustavo Fring","author_url":"https://www.pexels.com/@gustavo-fring","source_url":"https://www.pexels.com/photo/a-man-and-a-woman-holding-a-cardboard-box-6699395/"}', examples = '[{"en":"Volunteers distributed food and water to families after the storm.","vi":"Các tình nguyện viên đã phát thực phẩm và nước cho các gia đình sau cơn bão.","image_url":"https://images.pexels.com/photos/6646878/pexels-photo-6646878.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The company distributes its products to over forty countries.","vi":"Công ty phân phối sản phẩm của mình tới hơn bốn mươi quốc gia.","image_url":"https://images.pexels.com/photos/32399796/pexels-photo-32399796.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Wealth is not evenly distributed across the population.","vi":"Của cải không được phân bổ đồng đều trong dân cư.","image_url":"https://images.pexels.com/photos/29675062/pexels-photo-29675062.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'distribute';
UPDATE preset_deck_cards SET ipa = '/ɪˈkɑːnəmi/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eco/econo/economy__us_1.mp3', image_url = 'https://images.pexels.com/photos/10531120/pexels-photo-10531120.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Zucker Pop","author_url":"https://www.pexels.com/@zucker-pop-140939669","source_url":"https://www.pexels.com/photo/stacks-of-silver-and-gold-coins-in-close-up-photography-10531120/"}', examples = '[{"en":"The global economy grew more slowly than expected last year.","vi":"Năm ngoái, nền kinh tế toàn cầu tăng trưởng chậm hơn dự kiến.","image_url":"https://images.pexels.com/photos/7412102/pexels-photo-7412102.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Tourism plays an important role in the local economy.","vi":"Du lịch đóng vai trò quan trọng trong nền kinh tế địa phương.","image_url":"https://images.pexels.com/photos/34835271/pexels-photo-34835271.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Experts believe the economy will recover by next spring.","vi":"Các chuyên gia tin rằng nền kinh tế sẽ phục hồi vào mùa xuân tới.","image_url":"https://images.pexels.com/photos/39121210/pexels-photo-39121210.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'economy';
UPDATE preset_deck_cards SET ipa = '/ɪnˈvaɪrənmənt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envir/environment__us_2_rr.mp3', image_url = 'https://images.pexels.com/photos/4231781/pexels-photo-4231781.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Jorge Bilbao","author_url":"https://www.pexels.com/@bilbaojl","source_url":"https://www.pexels.com/photo/rippled-river-between-greenery-mountains-under-sky-4231781/"}', examples = '[{"en":"Plastic waste is causing serious damage to the environment.","vi":"Rác thải nhựa đang gây thiệt hại nghiêm trọng cho môi trường.","image_url":"https://images.pexels.com/photos/8770258/pexels-photo-8770258.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Children learn best in a safe and friendly environment.","vi":"Trẻ em học tốt nhất trong một môi trường an toàn và thân thiện.","image_url":"https://images.pexels.com/photos/6725335/pexels-photo-6725335.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Staff say the company offers a pleasant working environment.","vi":"Nhân viên cho biết công ty có môi trường làm việc dễ chịu.","image_url":"https://images.pexels.com/photos/13062477/pexels-photo-13062477.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'environment';
UPDATE preset_deck_cards SET ipa = '/ɪˈstæblɪʃ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estab/establish__us_2.mp3', image_url = 'https://images.pexels.com/photos/7207643/pexels-photo-7207643.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"𝗛&𝗖𝗢 　","author_url":"https://www.pexels.com/@hngstrm","source_url":"https://www.pexels.com/photo/staff-only-signage-on-the-door-7207643/"}', examples = '[{"en":"The research center was established in 1998 to study ocean pollution.","vi":"Trung tâm nghiên cứu được thành lập năm 1998 để nghiên cứu ô nhiễm đại dương.","image_url":"https://images.pexels.com/photos/15304868/pexels-photo-15304868.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The two countries established trade links in the early 1990s.","vi":"Hai nước đã thiết lập quan hệ thương mại vào đầu những năm 1990.","image_url":"https://images.pexels.com/photos/9498282/pexels-photo-9498282.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Police are trying to establish the cause of the fire.","vi":"Cảnh sát đang cố gắng xác định nguyên nhân vụ cháy.","image_url":"https://images.pexels.com/photos/9739635/pexels-photo-9739635.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'establish';
UPDATE preset_deck_cards SET ipa = '/ˈestɪmeɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estim/estimate__us_2.mp3', image_url = 'https://images.pexels.com/photos/7491011/pexels-photo-7491011.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"RDNE Stock project","author_url":"https://www.pexels.com/@rdne","source_url":"https://www.pexels.com/photo/woman-uses-calculator-7491011/"}', examples = '[{"en":"Experts estimate that the project will cost two million dollars.","vi":"Các chuyên gia ước tính dự án sẽ tốn hai triệu đô la.","image_url":"https://images.pexels.com/photos/6590650/pexels-photo-6590650.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It is difficult to estimate how many people use the service.","vi":"Rất khó ước tính có bao nhiêu người sử dụng dịch vụ này.","image_url":"https://images.pexels.com/photos/31467490/pexels-photo-31467490.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The city''s population is estimated at around 1.5 million.","vi":"Dân số của thành phố ước tính vào khoảng 1,5 triệu người.","image_url":"https://images.pexels.com/photos/3120002/pexels-photo-3120002.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'estimate';
UPDATE preset_deck_cards SET ipa = '/ˈevɪdənt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evi/evide/evident__us_1.mp3', image_url = 'https://images.pexels.com/photos/16954318/pexels-photo-16954318.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"TREEDEO.ST","author_url":"https://www.pexels.com/@treedeo","source_url":"https://www.pexels.com/photo/hand-putting-evidence-number-on-pavement-on-crime-scene-16954318/"}', examples = '[{"en":"It was evident that the students had not read the article.","vi":"Rõ ràng là các sinh viên đã không đọc bài báo đó.","image_url":"https://images.pexels.com/photos/5537507/pexels-photo-5537507.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The effects of climate change are already evident in many regions.","vi":"Tác động của biến đổi khí hậu đã hiện rõ ở nhiều khu vực.","image_url":"https://images.pexels.com/photos/35279538/pexels-photo-35279538.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Her love of science was evident from an early age.","vi":"Niềm yêu thích khoa học của cô ấy đã thể hiện rõ từ khi còn nhỏ.","image_url":"https://images.pexels.com/photos/30473621/pexels-photo-30473621.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'evident';
UPDATE preset_deck_cards SET ipa = '/ˈekspɔːrt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expor/export__us_2.mp3', image_url = 'https://images.pexels.com/photos/18874291/pexels-photo-18874291.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"TwoSix ZeroFive","author_url":"https://www.pexels.com/@twosix-zerofive-771736124","source_url":"https://www.pexels.com/photo/man-standing-in-container-with-bottles-18874291/"}', examples = '[{"en":"Coffee is one of the country''s main exports.","vi":"Cà phê là một trong những mặt hàng xuất khẩu chính của đất nước.","image_url":"https://images.pexels.com/photos/17052668/pexels-photo-17052668.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Rice exports rose by ten percent last year.","vi":"Năm ngoái, xuất khẩu gạo tăng mười phần trăm.","image_url":"https://images.pexels.com/photos/37051981/pexels-photo-37051981.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The factory produces furniture mainly for export.","vi":"Nhà máy sản xuất đồ nội thất chủ yếu để xuất khẩu.","image_url":"https://images.pexels.com/photos/32399707/pexels-photo-32399707.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'export';
UPDATE preset_deck_cards SET ipa = '/ˈfæktər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facto/factor__us_2.mp3', image_url = 'https://images.pexels.com/photos/38795663/pexels-photo-38795663.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Travel with  Lenses","author_url":"https://www.pexels.com/@travel-with-lenses-734723610","source_url":"https://www.pexels.com/photo/cyclists-racing-in-copenhagen-city-event-38795663/"}', examples = '[{"en":"Cost is an important factor when choosing a university.","vi":"Chi phí là một yếu tố quan trọng khi chọn trường đại học.","image_url":"https://images.pexels.com/photos/7054368/pexels-photo-7054368.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Several factors led to the fall in sales.","vi":"Một số yếu tố đã dẫn đến sự sụt giảm doanh số.","image_url":"https://images.pexels.com/photos/7956393/pexels-photo-7956393.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Smoking is a major risk factor for heart disease.","vi":"Hút thuốc là một yếu tố nguy cơ chính gây bệnh tim.","image_url":"https://images.pexels.com/photos/5812982/pexels-photo-5812982.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'factor';
UPDATE preset_deck_cards SET ipa = '/ˈfaɪnæns/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finan/finance__us_1_rr.mp3', image_url = 'https://images.pexels.com/photos/4968631/pexels-photo-4968631.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"https://kaboompics.com/","author_url":"https://www.pexels.com/@karola-g","source_url":"https://www.pexels.com/photo/counting-dollar-bills-4968631/"}', examples = '[{"en":"She has a degree in finance from a leading business school.","vi":"Cô ấy có bằng tài chính của một trường kinh doanh hàng đầu.","image_url":"https://images.pexels.com/photos/37846676/pexels-photo-37846676.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Many students struggle to manage their personal finances.","vi":"Nhiều sinh viên gặp khó khăn trong việc quản lý tài chính cá nhân.","image_url":"https://images.pexels.com/photos/10994723/pexels-photo-10994723.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The finance department will review the budget next week.","vi":"Phòng tài chính sẽ xem xét ngân sách vào tuần tới.","image_url":"https://images.pexels.com/photos/221174/pexels-photo-221174.png?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'finance';
UPDATE preset_deck_cards SET ipa = '/ˈfɔːrmjələ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/formu/formula__us_1.mp3', image_url = 'https://images.pexels.com/photos/3781338/pexels-photo-3781338.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Jeswin  Thomas","author_url":"https://www.pexels.com/@jeswin","source_url":"https://www.pexels.com/photo/person-writing-on-white-board-3781338/"}', examples = '[{"en":"Students must learn the formula for the area of a circle.","vi":"Học sinh phải học công thức tính diện tích hình tròn.","image_url":"https://images.pexels.com/photos/39191014/pexels-photo-39191014.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The chemical formula for water is H2O.","vi":"Công thức hóa học của nước là H2O.","image_url":"https://images.pexels.com/photos/3825468/pexels-photo-3825468.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"There is no simple formula for success in business.","vi":"Không có công thức đơn giản nào để thành công trong kinh doanh.","image_url":"https://images.pexels.com/photos/39191023/pexels-photo-39191023.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'formula';
UPDATE preset_deck_cards SET ipa = '/ˈfʌŋkʃn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funct/function__us_4.mp3', image_url = 'https://images.pexels.com/photos/37911188/pexels-photo-37911188.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Shubham Dhage","author_url":"https://www.pexels.com/@shubhamdhage","source_url":"https://www.pexels.com/photo/colorful-geometric-boxes-with-mathematical-symbols-37911188/"}', examples = '[{"en":"The main function of the heart is to pump blood around the body.","vi":"Chức năng chính của tim là bơm máu đi khắp cơ thể.","image_url":"https://images.pexels.com/photos/5340267/pexels-photo-5340267.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This app has a very useful search function.","vi":"Ứng dụng này có chức năng tìm kiếm rất hữu ích.","image_url":"https://images.pexels.com/photos/5807811/pexels-photo-5807811.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"In this lesson, we will learn how to draw the graph of a function.","vi":"Trong bài học này, chúng ta sẽ học cách vẽ đồ thị của một hàm số.","image_url":"https://images.pexels.com/photos/8482035/pexels-photo-8482035.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'function';
UPDATE preset_deck_cards SET ipa = '/aɪˈdentɪfaɪ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identify__us_3.mp3', image_url = 'https://images.pexels.com/photos/8382611/pexels-photo-8382611.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"cottonbro studio","author_url":"https://www.pexels.com/@cottonbro","source_url":"https://www.pexels.com/photo/close-up-photo-of-fingerpints-on-paper-8382611/"}', examples = '[{"en":"The study identified three main causes of stress at work.","vi":"Nghiên cứu đã xác định ba nguyên nhân chính gây căng thẳng tại nơi làm việc.","image_url":"https://images.pexels.com/photos/5908779/pexels-photo-5908779.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Can you identify the bird in this picture?","vi":"Bạn có nhận diện được con chim trong bức ảnh này không?","image_url":"https://images.pexels.com/photos/8073783/pexels-photo-8073783.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Teachers need to identify students who need extra help early.","vi":"Giáo viên cần sớm nhận ra những học sinh cần được hỗ trợ thêm.","image_url":"https://images.pexels.com/photos/8363012/pexels-photo-8363012.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'identify';
UPDATE preset_deck_cards SET ipa = '/ˈɪnkʌm/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incom/income__us_1_rr.mp3', image_url = 'https://images.pexels.com/photos/7654617/pexels-photo-7654617.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200', image_attribution = '{"source":"pexels","author":"Pavel Danilyuk","author_url":"https://www.pexels.com/@pavel-danilyuk","source_url":"https://www.pexels.com/photo/woman-wearing-eyeglasses-while-sitting-on-office-chair-7654617/"}', examples = '[{"en":"Families with low incomes will receive extra support.","vi":"Các gia đình có thu nhập thấp sẽ được hỗ trợ thêm.","image_url":"https://images.pexels.com/photos/8297589/pexels-photo-8297589.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Tourism is the island''s main source of income.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo.","image_url":"https://images.pexels.com/photos/31421280/pexels-photo-31421280.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Her monthly income increased after she changed jobs.","vi":"Thu nhập hàng tháng của cô ấy tăng lên sau khi cô chuyển việc.","image_url":"https://images.pexels.com/photos/5900184/pexels-photo-5900184.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-01' AND english = 'income';
-- awl-1-02
UPDATE preset_deck_cards SET ipa = '/ˈɪndɪkeɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indic/indicate__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The results indicate a strong link between sleep and memory.","vi":"Kết quả cho thấy mối liên hệ chặt chẽ giữa giấc ngủ và trí nhớ."},{"en":"Recent surveys indicate that most employees prefer flexible working hours.","vi":"Các khảo sát gần đây chỉ ra rằng phần lớn nhân viên thích giờ làm việc linh hoạt.","image_url":"https://images.pexels.com/photos/18955784/pexels-photo-18955784.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"A red light on the panel indicates a problem with the power supply.","vi":"Đèn đỏ trên bảng điều khiển biểu thị sự cố về nguồn điện."}]' WHERE deck_code = 'awl-1-02' AND english = 'indicate';
UPDATE preset_deck_cards SET ipa = '/ˌɪndɪˈvɪdʒuəl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indiv/individual__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Teachers should pay attention to the individual needs of each student.","vi":"Giáo viên nên chú ý đến nhu cầu riêng của từng học sinh."},{"en":"The report looks at individual countries rather than the whole region.","vi":"Báo cáo xem xét từng quốc gia thay vì cả khu vực."},{"en":"The company rewards both team success and individual performance.","vi":"Công ty khen thưởng cả thành công của nhóm lẫn thành tích cá nhân."}]' WHERE deck_code = 'awl-1-02' AND english = 'individual';
UPDATE preset_deck_cards SET ipa = '/ɪnˈtɜːrprət/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interpret__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Researchers must be careful when they interpret results from small samples.","vi":"Các nhà nghiên cứu phải cẩn trọng khi diễn giải kết quả từ các mẫu nhỏ."},{"en":"His silence was interpreted as agreement by the rest of the team.","vi":"Sự im lặng của anh ấy được những người còn lại trong nhóm hiểu là đồng ý."},{"en":"She interpreted for the visiting engineers during the factory tour.","vi":"Cô ấy phiên dịch cho các kỹ sư đến thăm trong chuyến tham quan nhà máy.","image_url":"https://images.pexels.com/photos/20684151/pexels-photo-20684151.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-02' AND english = 'interpret';
UPDATE preset_deck_cards SET ipa = '/ɪnˈvɑːlv/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invol/involve__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The job involves a lot of travel within the region.","vi":"Công việc này đòi hỏi phải đi lại nhiều trong khu vực."},{"en":"The study involved more than two thousand adults from five countries.","vi":"Nghiên cứu có sự tham gia của hơn hai nghìn người trưởng thành từ năm quốc gia."},{"en":"Parents should be involved in decisions about their children''s education.","vi":"Cha mẹ nên được tham gia vào các quyết định về việc học của con cái."}]' WHERE deck_code = 'awl-1-02' AND english = 'involve';
UPDATE preset_deck_cards SET ipa = '/ˈɪʃuː/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iss/issue/issue__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Climate change is a major issue for coastal cities.","vi":"Biến đổi khí hậu là một vấn đề lớn đối với các thành phố ven biển."},{"en":"The committee will discuss the issue at its next meeting.","vi":"Ủy ban sẽ thảo luận vấn đề này tại cuộc họp tới."},{"en":"The article appeared in the latest issue of the journal.","vi":"Bài báo được đăng trong số mới nhất của tạp chí."}]' WHERE deck_code = 'awl-1-02' AND english = 'issue';
UPDATE preset_deck_cards SET ipa = '/ˈleɪbər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/labou/labour__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The factory moved production abroad to reduce labour costs.","vi":"Nhà máy chuyển hoạt động sản xuất ra nước ngoài để giảm chi phí nhân công."},{"en":"Many farms rely on seasonal labour during the harvest.","vi":"Nhiều trang trại dựa vào lao động thời vụ trong mùa thu hoạch."},{"en":"The labour market has become more competitive for young graduates.","vi":"Thị trường lao động đã trở nên cạnh tranh hơn đối với sinh viên mới tốt nghiệp."}]' WHERE deck_code = 'awl-1-02' AND english = 'labour';
UPDATE preset_deck_cards SET ipa = '/ˈliːɡl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legal/legal__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The company sought legal advice before signing the contract.","vi":"Công ty đã tìm tư vấn pháp lý trước khi ký hợp đồng."},{"en":"Is it legal to drive with a foreign license here?","vi":"Ở đây lái xe bằng giấy phép nước ngoài có hợp pháp không?"},{"en":"Every country has its own legal system and traditions.","vi":"Mỗi quốc gia đều có hệ thống pháp luật và truyền thống riêng."}]' WHERE deck_code = 'awl-1-02' AND english = 'legal';
UPDATE preset_deck_cards SET ipa = '/ˈledʒɪsleɪt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legis/legislate__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Many governments have begun to legislate against plastic waste.","vi":"Nhiều chính phủ đã bắt đầu ban hành luật chống rác thải nhựa."},{"en":"It is difficult to legislate for every possible situation.","vi":"Thật khó để ban hành luật cho mọi tình huống có thể xảy ra.","image_url":"https://images.pexels.com/photos/9755375/pexels-photo-9755375.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Several states have legislated to protect workers'' personal data.","vi":"Một số bang đã ban hành luật để bảo vệ dữ liệu cá nhân của người lao động."}]' WHERE deck_code = 'awl-1-02' AND english = 'legislate';
UPDATE preset_deck_cards SET ipa = '/ˈmeɪdʒər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/maj/major/major__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Traffic is a major cause of air pollution in large cities.","vi":"Giao thông là nguyên nhân chính gây ô nhiễm không khí ở các thành phố lớn."},{"en":"The new policy led to major changes in how staff are trained.","vi":"Chính sách mới đã dẫn đến những thay đổi lớn trong cách đào tạo nhân viên."},{"en":"Researchers faced a major problem when their funding was cut.","vi":"Các nhà nghiên cứu gặp phải một vấn đề lớn khi kinh phí bị cắt giảm."}]' WHERE deck_code = 'awl-1-02' AND english = 'major';
UPDATE preset_deck_cards SET ipa = '/ˈmeθəd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/metho/method__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"This teaching method encourages students to work in small groups.","vi":"Phương pháp giảng dạy này khuyến khích học sinh làm việc theo nhóm nhỏ."},{"en":"Which method did you use to collect the data?","vi":"Bạn đã dùng phương pháp nào để thu thập dữ liệu?"},{"en":"Bank transfer is still the most common method of payment.","vi":"Chuyển khoản ngân hàng vẫn là phương thức thanh toán phổ biến nhất."}]' WHERE deck_code = 'awl-1-02' AND english = 'method';
UPDATE preset_deck_cards SET ipa = '/əˈkɜːr/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occur/occur__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Most workplace accidents occur when safety rules are ignored.","vi":"Hầu hết tai nạn lao động xảy ra khi các quy định an toàn bị phớt lờ."},{"en":"The disease occurs mainly in tropical regions.","vi":"Căn bệnh này chủ yếu xuất hiện ở các vùng nhiệt đới."},{"en":"It never occurred to me that the data might be wrong.","vi":"Tôi chưa bao giờ nghĩ rằng dữ liệu có thể bị sai."}]' WHERE deck_code = 'awl-1-02' AND english = 'occur';
UPDATE preset_deck_cards SET ipa = '/pərˈsɛnt/', audio_src = NULL, image_url = NULL, image_attribution = NULL, examples = '[{"en":"Sales rose by 15 percent in the first quarter.","vi":"Doanh số tăng 15 phần trăm trong quý đầu tiên."},{"en":"Only 40 percent of the students completed the online survey.","vi":"Chỉ 40 phần trăm sinh viên hoàn thành bản khảo sát trực tuyến."},{"en":"About 70 percent of the Earth''s surface is covered by water.","vi":"Khoảng 70 phần trăm bề mặt Trái Đất được bao phủ bởi nước."}]' WHERE deck_code = 'awl-1-02' AND english = 'percent';
UPDATE preset_deck_cards SET ipa = '/ˈpɪriəd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perio/period__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The project will be completed over a period of three years.","vi":"Dự án sẽ được hoàn thành trong khoảng thời gian ba năm."},{"en":"Prices remained fairly stable during this period of growth.","vi":"Giá cả vẫn khá ổn định trong suốt giai đoạn tăng trưởng này."},{"en":"New employees usually have a trial period of two months.","vi":"Nhân viên mới thường có thời gian thử việc hai tháng."}]' WHERE deck_code = 'awl-1-02' AND english = 'period';
UPDATE preset_deck_cards SET ipa = '/ˈpɑːləsi/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polic/policy__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The government introduced a new policy to support small businesses.","vi":"Chính phủ đã đưa ra một chính sách mới để hỗ trợ doanh nghiệp nhỏ."},{"en":"Our company has a strict policy on the use of personal phones.","vi":"Công ty chúng tôi có quy định nghiêm ngặt về việc sử dụng điện thoại cá nhân."},{"en":"Economic policy should focus on creating more stable jobs.","vi":"Chính sách kinh tế nên tập trung vào việc tạo ra nhiều việc làm ổn định hơn."}]' WHERE deck_code = 'awl-1-02' AND english = 'policy';
UPDATE preset_deck_cards SET ipa = '/ˈprɪnsəpl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principle__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The course explains the basic principles of economics.","vi":"Khóa học giải thích những nguyên lý cơ bản của kinh tế học."},{"en":"Fairness is a key principle in our hiring process.","vi":"Công bằng là một nguyên tắc then chốt trong quy trình tuyển dụng của chúng tôi."},{"en":"In principle, the plan is good, but it may be too expensive.","vi":"Về nguyên tắc, kế hoạch này tốt, nhưng có thể quá tốn kém."}]' WHERE deck_code = 'awl-1-02' AND english = 'principle';
UPDATE preset_deck_cards SET ipa = '/prəʊˈsiːd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/proceed__us_1_rr.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"After a short break, the meeting proceeded as planned.","vi":"Sau giờ nghỉ ngắn, cuộc họp tiếp tục như dự kiến."},{"en":"The city council decided to proceed with the new housing project.","vi":"Hội đồng thành phố quyết định tiến hành dự án nhà ở mới."},{"en":"Passengers on the morning flight should proceed to gate 12.","vi":"Hành khách của chuyến bay buổi sáng vui lòng đi đến cổng số 12."}]' WHERE deck_code = 'awl-1-02' AND english = 'proceed';
UPDATE preset_deck_cards SET ipa = '/ˈprɑːses/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/process__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Learning a language is a slow process that takes patience.","vi":"Học một ngôn ngữ là một quá trình chậm, cần sự kiên nhẫn."},{"en":"The company has simplified its application process for new customers.","vi":"Công ty đã đơn giản hóa quy trình đăng ký cho khách hàng mới."},{"en":"We are still in the process of reviewing your request.","vi":"Chúng tôi vẫn đang trong quá trình xem xét yêu cầu của bạn."}]' WHERE deck_code = 'awl-1-02' AND english = 'process';
UPDATE preset_deck_cards SET ipa = '/rɪˈkwaɪər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/requi/require__us_3.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Most jobs in this field require a university degree.","vi":"Hầu hết công việc trong lĩnh vực này đòi hỏi bằng đại học."},{"en":"All visitors are required to sign in at reception.","vi":"Tất cả khách đến thăm đều được yêu cầu đăng ký tại quầy lễ tân."},{"en":"The experiment requires careful planning and accurate measurement.","vi":"Thí nghiệm này cần được lên kế hoạch cẩn thận và đo đạc chính xác."}]' WHERE deck_code = 'awl-1-02' AND english = 'require';
UPDATE preset_deck_cards SET ipa = '/ˈriːsɜːrtʃ/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resea/research__us_2_rr.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Recent research shows that regular exercise can improve memory.","vi":"Nghiên cứu gần đây cho thấy tập thể dục thường xuyên có thể cải thiện trí nhớ."},{"en":"She is doing research on renewable energy at the university.","vi":"Cô ấy đang nghiên cứu về năng lượng tái tạo tại trường đại học.","image_url":"https://images.pexels.com/photos/6208712/pexels-photo-6208712.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"More research is needed before the drug can be approved.","vi":"Cần thêm nghiên cứu trước khi loại thuốc này được phê duyệt."}]' WHERE deck_code = 'awl-1-02' AND english = 'research';
UPDATE preset_deck_cards SET ipa = '/rɪˈspɑːnd/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/respond__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The company responded quickly to customer complaints.","vi":"Công ty đã phản hồi nhanh chóng trước khiếu nại của khách hàng."},{"en":"Please respond to this email by Friday.","vi":"Vui lòng trả lời email này trước thứ Sáu."},{"en":"Patients usually respond well to this kind of treatment.","vi":"Bệnh nhân thường đáp ứng tốt với phương pháp điều trị này."}]' WHERE deck_code = 'awl-1-02' AND english = 'respond';
UPDATE preset_deck_cards SET ipa = '/rəʊl/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rol/role_/role__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Technology plays an important role in modern healthcare.","vi":"Công nghệ đóng vai trò quan trọng trong ngành y tế hiện đại."},{"en":"Her role in the project is to manage the budget.","vi":"Vai trò của cô ấy trong dự án là quản lý ngân sách."},{"en":"He was offered the leading role in the school play.","vi":"Cậu ấy được mời đóng vai chính trong vở kịch của trường."}]' WHERE deck_code = 'awl-1-02' AND english = 'role';
UPDATE preset_deck_cards SET ipa = '/ˈsekʃn/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secti/section__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Please read the first section of the report before the meeting.","vi":"Vui lòng đọc phần đầu tiên của báo cáo trước cuộc họp."},{"en":"The test has three sections: reading, writing, and listening.","vi":"Bài kiểm tra có ba phần: đọc, viết và nghe."},{"en":"The fruit and vegetable section is at the back of the store.","vi":"Khu rau củ quả nằm ở phía sau cửa hàng."}]' WHERE deck_code = 'awl-1-02' AND english = 'section';
UPDATE preset_deck_cards SET ipa = '/ˈsektər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secto/sector__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The public sector employs nearly a quarter of the workforce.","vi":"Khu vực công sử dụng gần một phần tư lực lượng lao động."},{"en":"Jobs in the technology sector are growing quickly.","vi":"Việc làm trong lĩnh vực công nghệ đang tăng nhanh."},{"en":"Tourism is the largest sector of the local economy.","vi":"Du lịch là ngành lớn nhất của nền kinh tế địa phương."}]' WHERE deck_code = 'awl-1-02' AND english = 'sector';
UPDATE preset_deck_cards SET ipa = '/sɪɡˈnɪfɪkənt/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significant__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"There has been a significant increase in online shopping.","vi":"Mua sắm trực tuyến đã có sự gia tăng đáng kể."},{"en":"The study found no significant difference between the two groups.","vi":"Nghiên cứu không tìm thấy khác biệt có ý nghĩa giữa hai nhóm."},{"en":"This was a significant moment in the history of medicine.","vi":"Đây là một thời khắc quan trọng trong lịch sử y học."}]' WHERE deck_code = 'awl-1-02' AND english = 'significant';
UPDATE preset_deck_cards SET ipa = '/ˈsɪmələr/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simil/similar__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The two reports reached similar conclusions about the causes of the problem.","vi":"Hai báo cáo đưa ra những kết luận tương tự nhau về nguyên nhân của vấn đề."},{"en":"My new job is similar to my old one.","vi":"Công việc mới của tôi giống với công việc cũ."},{"en":"Similar results were found in studies in other countries.","vi":"Các nghiên cứu ở những nước khác cho ra kết quả tương tự."}]' WHERE deck_code = 'awl-1-02' AND english = 'similar';
UPDATE preset_deck_cards SET ipa = '/sɔːrs/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/sourc/source__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Fruit is a good source of vitamins and fiber.","vi":"Trái cây là một nguồn vitamin và chất xơ tốt."},{"en":"Always check your sources before you cite them in an essay.","vi":"Hãy luôn kiểm tra nguồn tài liệu trước khi trích dẫn chúng trong bài luận."},{"en":"Engineers are still trying to find the source of the leak.","vi":"Các kỹ sư vẫn đang cố tìm ra nguồn gốc của chỗ rò rỉ."}]' WHERE deck_code = 'awl-1-02' AND english = 'source';
UPDATE preset_deck_cards SET ipa = '/spəˈsɪfɪk/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specific__us_1.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Can you give me a specific example of the problem?","vi":"Bạn có thể cho tôi một ví dụ cụ thể về vấn đề này không?"},{"en":"The training is designed for the specific needs of nurses.","vi":"Khóa đào tạo được thiết kế cho nhu cầu đặc thù của điều dưỡng."},{"en":"These plants grow only under very specific conditions.","vi":"Những loài cây này chỉ phát triển trong những điều kiện rất riêng biệt."}]' WHERE deck_code = 'awl-1-02' AND english = 'specific';
UPDATE preset_deck_cards SET ipa = '/ˈstrʌktʃər/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/struc/structure__us_2.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"The essay has a clear structure with an introduction and a conclusion.","vi":"Bài luận có cấu trúc rõ ràng với phần mở bài và phần kết luận."},{"en":"Scientists studied the structure of the cell in great detail.","vi":"Các nhà khoa học đã nghiên cứu rất chi tiết cấu trúc của tế bào."},{"en":"Last year, the company changed its management structure.","vi":"Năm ngoái, công ty đã thay đổi cơ cấu quản lý."}]' WHERE deck_code = 'awl-1-02' AND english = 'structure';
UPDATE preset_deck_cards SET ipa = '/ˈθiːəri/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theor/theory__us_2_rr.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Economic theory cannot always predict how people will behave.","vi":"Lý thuyết kinh tế không phải lúc nào cũng dự đoán được con người sẽ hành xử ra sao."},{"en":"The idea sounds good in theory, but it rarely works in practice.","vi":"Ý tưởng này nghe hay trên lý thuyết, nhưng hiếm khi hiệu quả trong thực tế."},{"en":"Scientists have developed a new theory to explain the data.","vi":"Các nhà khoa học đã xây dựng một lý thuyết mới để giải thích dữ liệu.","image_url":"https://images.pexels.com/photos/210804/pexels-photo-210804.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]' WHERE deck_code = 'awl-1-02' AND english = 'theory';
UPDATE preset_deck_cards SET ipa = '/ˈveri/', audio_src = 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/vary_/vary__us_4.mp3', image_url = NULL, image_attribution = NULL, examples = '[{"en":"Hotel prices vary greatly depending on the time of year.","vi":"Giá khách sạn thay đổi rất nhiều tùy theo thời điểm trong năm."},{"en":"Opinions on the new policy varied widely among staff.","vi":"Ý kiến của nhân viên về chính sách mới rất khác nhau."},{"en":"Try to vary your diet by eating different kinds of vegetables.","vi":"Hãy cố gắng đa dạng hóa chế độ ăn bằng cách ăn nhiều loại rau khác nhau."}]' WHERE deck_code = 'awl-1-02' AND english = 'vary';
